import{_ as e,o as d,c as o,a2 as a}from"./chunks/framework.Ch4PdLd_.js";const _=JSON.parse('{"title":"环境变量","description":"","frontmatter":{},"headers":[],"relativePath":"reference/environment-variables.md","filePath":"reference/environment-variables.md"}'),c={name:"reference/environment-variables.md"};function r(s,t,i,n,l,h){return d(),o("div",null,[...t[0]||(t[0]=[a(`<h1 id="环境变量" tabindex="-1">环境变量 <a class="header-anchor" href="#环境变量" aria-label="Permalink to &quot;环境变量&quot;">​</a></h1><p>nek 用环境变量配置进程、传递会话信息和提供服务商凭据。</p><ul><li><code>NEK_*</code> 变量配置 nek 进程；</li><li>nek 会设置进程标记，让子进程知道自己是被 nek 启动的；</li><li>模型调用的 shell 工具会收到描述当前会话的 <code>NEK_*</code> 变量；</li><li>共享的服务商和终端组件保留了少量 <code>PI_*</code> 兼容变量。</li></ul><p>服务商 API key 的变量见 <a href="/nekcode/reference/providers#env">服务商认证</a>。</p><h2 id="process" tabindex="-1">进程配置 <a class="header-anchor" href="#process" aria-label="Permalink to &quot;进程配置 {#process}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>变量</th><th>说明</th></tr></thead><tbody><tr><td><code>NEK_CODING_AGENT_DIR</code></td><td>用户数据目录，默认 <code>~/.nek/agent</code></td></tr><tr><td><code>NEK_CODING_AGENT_SESSION_DIR</code></td><td>会话存储目录，会被 <code>--session-dir</code> 覆盖</td></tr><tr><td><code>NEK_PACKAGE_DIR</code></td><td>覆盖包目录，适用于 Nix、Guix 等 store 路径</td></tr><tr><td><code>NEK_OFFLINE</code></td><td>关闭启动时的网络活动（模型目录刷新、工具下载等），同 <code>--offline</code></td></tr><tr><td><code>NEK_EXPERIMENTAL</code></td><td>设为 <code>1</code> 时启用实验性的 server/client 命令</td></tr><tr><td><code>NEK_TELEMETRY</code></td><td>覆盖安装遥测和服务商来源标识请求头（<code>1</code>/<code>true</code>/<code>yes</code> 或 <code>0</code>/<code>false</code>/<code>no</code>）</td></tr><tr><td><code>NEK_SHARE_VIEWER_URL</code></td><td>覆盖 <code>/share</code> 使用的查看器地址</td></tr><tr><td><code>NEK_RADIUS_GATEWAY</code></td><td>覆盖 Radius 网关地址（用于分享上传等）</td></tr><tr><td><code>NEK_CLEAR_ON_SHRINK</code></td><td>设为 <code>1</code> 时内容缩短后清除空行</td></tr><tr><td><code>NEK_HARDWARE_CURSOR</code></td><td>设为 <code>1</code> 时显示硬件光标（帮助输入法定位）</td></tr><tr><td><code>NEK_BUN</code></td><td>OpenTUI 界面使用的 Bun 可执行文件路径</td></tr><tr><td><code>NEK_STARTUP_BENCHMARK</code></td><td>交互模式下启用启动性能测量</td></tr><tr><td><code>NEK_TIMING</code></td><td>设为 <code>1</code> 时启用启动耗时统计</td></tr></tbody></table><h2 id="installer" tabindex="-1">安装脚本 <a class="header-anchor" href="#installer" aria-label="Permalink to &quot;安装脚本 {#installer}&quot;">​</a></h2><p>运行安装脚本或 <code>nek update</code> 时读取，见 <a href="/nekcode/start/install#install-options">安装</a>：</p><table tabindex="0"><thead><tr><th>变量</th><th>说明</th></tr></thead><tbody><tr><td><code>NEK_INSTALL_DIR</code></td><td>源码目录</td></tr><tr><td><code>NEK_BIN_DIR</code></td><td><code>nek</code> 命令所在目录</td></tr><tr><td><code>NEK_CHANNEL</code></td><td>更新通道：<code>stable</code> 或 <code>dev</code></td></tr><tr><td><code>NEK_BRANCH</code></td><td>dev 通道跟踪的分支</td></tr><tr><td><code>NEK_REPO_URL</code></td><td>仓库地址</td></tr><tr><td><code>NEK_SKIP_TOOLS</code></td><td>设为 <code>1</code> 跳过 fd/rg/ast-grep 的准备</td></tr><tr><td><code>NEK_INSTALL_BUN</code></td><td>设为 <code>1</code> 在没有 Bun 时自动安装</td></tr></tbody></table><h2 id="markers" tabindex="-1">进程标记 <a class="header-anchor" href="#markers" aria-label="Permalink to &quot;进程标记 {#markers}&quot;">​</a></h2><p>CLI 和 RPC 入口会设置：</p><ul><li><code>AI_AGENT=nek</code>：标识启动者是 nek；</li><li><code>NEK_CODING_AGENT=true</code>：标识这是 nek 的子进程。</li></ul><p>子进程继承这两个标记。它们与会话无关，通过 SDK 嵌入时不会自动设置。</p><h2 id="shell-env" tabindex="-1">shell 工具中的会话信息 <a class="header-anchor" href="#shell-env" aria-label="Permalink to &quot;shell 工具中的会话信息 {#shell-env}&quot;">​</a></h2><p>模型调用的 <code>bash</code> 和 <code>powershell</code> 命令会收到当前会话的状态：</p><table tabindex="0"><thead><tr><th>变量</th><th>说明</th></tr></thead><tbody><tr><td><code>NEK_SESSION_ID</code></td><td>当前会话 ID</td></tr><tr><td><code>NEK_SESSION_FILE</code></td><td>当前会话文件（<code>.sqlite</code>）的绝对路径；临时会话时不设置</td></tr><tr><td><code>NEK_PROVIDER</code></td><td>当前选择的服务商</td></tr><tr><td><code>NEK_MODEL</code></td><td>当前选择的模型 ID</td></tr><tr><td><code>NEK_REASONING_LEVEL</code></td><td>当前生效的思考等级</td></tr></tbody></table><p>每条命令启动时取值，切换模型或思考等级会影响下一条命令，不需要重启 nek。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">printf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;%s/%s\\n&#39;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$NEK_PROVIDER</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$NEK_MODEL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">printf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;reasoning=%s session=%s\\n&#39;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$NEK_REASONING_LEVEL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$NEK_SESSION_ID</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span></code></pre></div><p>这些变量<strong>不会</strong>注入你输入的 <code>!</code> 和 <code>!!</code> 命令。自定义 shell 工具可以用 <code>exposeSessionEnvironment: false</code> 关闭注入。</p><h2 id="compat" tabindex="-1">兼容变量 <a class="header-anchor" href="#compat" aria-label="Permalink to &quot;兼容变量 {#compat}&quot;">​</a></h2><p>以下变量由 nek 使用的共享组件读取，保留原来的名字：</p><table tabindex="0"><thead><tr><th>变量</th><th>说明</th></tr></thead><tbody><tr><td><code>PI_HYPERLINKS</code></td><td><code>1</code>/<code>0</code>/<code>auto</code>，覆盖 OSC 8 超链接检测</td></tr><tr><td><code>PI_IMAGE_PROTOCOL</code></td><td><code>kitty</code>/<code>iterm2</code>/<code>none</code>/<code>auto</code>，覆盖内嵌图片协议检测</td></tr><tr><td><code>PI_TRUE_COLOR</code></td><td><code>1</code>/<code>0</code>/<code>auto</code>，覆盖真彩色检测</td></tr><tr><td><code>PI_TUI_ESC_TIMEOUT</code></td><td>终端 Escape 序列的等待时间</td></tr><tr><td><code>PI_TUI_WRITE_LOG</code></td><td>把原始 ANSI 输出写入日志，用于诊断渲染问题</td></tr><tr><td><code>PI_CACHE_RETENTION</code></td><td>服务商提示词缓存的保留档位</td></tr></tbody></table><p>对应的设置优先于这些变量，见 <a href="/nekcode/platform/terminal-setup#override">终端设置</a>。</p><h2 id="其他常用变量" tabindex="-1">其他常用变量 <a class="header-anchor" href="#其他常用变量" aria-label="Permalink to &quot;其他常用变量&quot;">​</a></h2><table tabindex="0"><thead><tr><th>变量</th><th>说明</th></tr></thead><tbody><tr><td><code>VISUAL</code>、<code>EDITOR</code></td><td><code>Ctrl+G</code> 使用的外部编辑器（设置 <code>externalEditor</code> 优先）</td></tr><tr><td><code>HTTP_PROXY</code>、<code>HTTPS_PROXY</code></td><td>代理（也可用设置 <code>httpProxy</code>）</td></tr><tr><td><code>LLAMA_BASE_URL</code>、<code>LLAMA_API_KEY</code></td><td>llama.cpp 路由服务的地址和 key，见 <a href="/nekcode/guide/local-models">本地模型</a></td></tr><tr><td><code>HF_TOKEN</code></td><td>Hugging Face token</td></tr></tbody></table>`,25)])])}const p=e(c,[["render",r]]);export{_ as __pageData,p as default};
